      default: 'Frontend Developer'
    },
    joinedAt: {
      type: Date,
      default: Date.now
    }
  }],
  maxSize: {
    type: Number,
    default: 4,
    min: 2,
    max: 10
  },
  requirements: {
    type: String,
    trim: true,
    maxlength: 500
  },
  skills: [String],
  lookingForMembers: {
    type: Boolean,
    default: true
  },
