teamSchema.index({ leader: 1 });
teamSchema.index({ 'members.userId': 1 });
teamSchema.index({ status: 1 });

// Virtual for current team size
teamSchema.virtual('currentSize').get(function() {
  return this.members.length + 1; // +1 for leader
});

// Virtual for available spots
teamSchema.virtual('availableSpots').get(function() {
  return this.maxSize - this.currentSize;
});

// Method to add member
teamSchema.methods.addMember = function(email, role = 'Frontend Developer') {
  // Check if team is full
  if (this.currentSize >= this.maxSize) {
    throw new Error('Team is already full');
  }

  // Check if user is already a member or leader
  if (this.leader === email) {
    throw new Error('User is already the team leader');
  }

  const existingMember = this.members.find(m => m.email === email);
  if (existingMember) {
    throw new Error('User is already a team member');
  }

  this.members.push({
    email,
    role,
    joinedAt: new Date()
  });

  // Update status if team is now complete
  if (this.currentSize >= this.maxSize) {
    this.status = 'complete';
    this.lookingForMembers = false;
  }

  return this.save();
};

// Method to remove member
teamSchema.methods.removeMember = function(email) {
  const memberIndex = this.members.findIndex(m => m.email === email);

  if (memberIndex === -1) {
    throw new Error('User is not a member of this team');
  }

  this.members.splice(memberIndex, 1);

  // Update status if team is no longer complete
  if (this.status === 'complete' && this.currentSize < this.maxSize) {
    this.status = 'forming';
  }

  return this.save();
};

// Method to toggle looking for members status
teamSchema.methods.toggleLookingForMembers = function() {
  // Can only look for members if team is not full
  if (this.currentSize >= this.maxSize) {
    this.lookingForMembers = false;
    this.status = 'complete';
  } else {
    this.lookingForMembers = !this.lookingForMembers;
    this.status = this.lookingForMembers ? 'forming' : 'complete';
  }

  return this.save();
};

// Method to check if user can join team
teamSchema.methods.canUserJoin = function(email) {
  // Check if team is looking for members
  if (!this.lookingForMembers) {
    return { canJoin: false, reason: 'Team is not looking for members' };
  }

  // Check if team is full
  if (this.currentSize >= this.maxSize) {
    return { canJoin: false, reason: 'Team is full' };
  }

  // Check if user is already leader or member
  if (this.leader === email) {
    return { canJoin: false, reason: 'User is already the team leader' };
  }

  const existingMember = this.members.find(m => m.email === email);
  if (existingMember) {
    return { canJoin: false, reason: 'User is already a team member' };
  }

  return { canJoin: true };
};

// Method to update team activity
teamSchema.methods.updateActivity = function() {
  this.communication.lastActivity = new Date();
  return this.save();
};

module.exports = mongoose.model('Team', teamSchema);

const bcrypt = require('bcrypt');
const { generateToken } = require('../middleware/security');

// In-memory user storage (replace with database in production)
const users = new Map();
const verifiedEmails = new Set();

class User {
  constructor(userData) {
    this.id = this.generateId();
    this.name = userData.name;
    this.email = userData.email.toLowerCase().trim();
    this.password = userData.password; // Will be hashed
    this.emailVerified = false;
    this.createdAt = new Date().toISOString();
    this.updatedAt = new Date().toISOString();
    this.lastLogin = null;
    this.loginAttempts = 0;
    this.lockedUntil = null;
  }

  generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  async hashPassword() {
    const saltRounds = 12;
    this.password = await bcrypt.hash(this.password, saltRounds);
  }

  async comparePassword(candidatePassword) {
    return await bcrypt.compare(candidatePassword, this.password);
  }

  generateAuthToken() {
    const payload = {
      id: this.id,
      email: this.email,
      name: this.name
    };
    return generateToken(payload);
  }

  toJSON() {
    // Return user data without sensitive information
    return {
      id: this.id,
      name: this.name,
      email: this.email,
      emailVerified: this.emailVerified,
      createdAt: this.createdAt,
      lastLogin: this.lastLogin
    };
  }

  // Static methods for user management
  static async create(userData) {
    // Validate required fields
    if (!userData.name || !userData.email || !userData.password) {
      throw new Error('Name, email, and password are required');
    }

    // Check if user already exists
    if (User.findByEmail(userData.email)) {
      throw new Error('User with this email already exists');
    }

    // Check if email is verified
    if (!verifiedEmails.has(userData.email.toLowerCase().trim())) {
      throw new Error('Email not verified. Please verify your email first.');
    }

    // Create new user
    const user = new User(userData);
    await user.hashPassword();
    user.emailVerified = true;

    // Save user
    users.set(user.id, user);

    // Remove email from verified set (one-time use)
    verifiedEmails.delete(userData.email.toLowerCase().trim());

    return user;
  }

  static findById(id) {
    return users.get(id);
  }

  static findByEmail(email) {
    const normalizedEmail = email.toLowerCase().trim();
    for (const user of users.values()) {
      if (user.email === normalizedEmail) {
        return user;
      }
    }
    return null;
  }

  static async authenticate(email, password) {
    const user = User.findByEmail(email);

    if (!user) {
      throw new Error('Invalid email or password');
    }

    // Check if account is locked
    if (user.lockedUntil && new Date() < new Date(user.lockedUntil)) {
      const remainingTime = Math.ceil((new Date(user.lockedUntil) - new Date()) / 1000);
      throw new Error(`Account locked. Try again in ${remainingTime} seconds.`);
    }

    const isValidPassword = await user.comparePassword(password);

    if (!isValidPassword) {
      // Increment login attempts
      user.loginAttempts++;
      user.updatedAt = new Date().toISOString();

      // Lock account after 5 failed attempts
      if (user.loginAttempts >= 5) {
        user.lockedUntil = new Date(Date.now() + 15 * 60 * 1000).toISOString(); // 15 minutes
        throw new Error('Account locked due to too many failed login attempts');
      }

      throw new Error('Invalid email or password');
    }

    // Reset login attempts on successful login
    user.loginAttempts = 0;
    user.lockedUntil = null;
    user.lastLogin = new Date().toISOString();
    user.updatedAt = new Date().toISOString();

    return user;
  }

  static markEmailAsVerified(email) {
    const normalizedEmail = email.toLowerCase().trim();
    verifiedEmails.add(normalizedEmail);
  }

  static isEmailVerified(email) {
    const normalizedEmail = email.toLowerCase().trim();
    return verifiedEmails.has(normalizedEmail);
  }

  static removeEmailVerification(email) {
    const normalizedEmail = email.toLowerCase().trim();
    verifiedEmails.delete(normalizedEmail);
  }

  static getAllUsers() {
    return Array.from(users.values()).map(user => user.toJSON());
  }

  static getUserCount() {
    return users.size;
  }

  static deleteUser(id) {
    return users.delete(id);
  }

  // Update user data
  async update(updateData) {
    const allowedFields = ['name', 'email'];

    for (const field of allowedFields) {
      if (updateData[field] !== undefined) {
        if (field === 'email') {
          // Check if new email already exists
          const existingUser = User.findByEmail(updateData[field]);
          if (existingUser && existingUser.id !== this.id) {
            throw new Error('Email already in use');
          }
          this[field] = updateData[field].toLowerCase().trim();
        } else {
          this[field] = updateData[field];
        }
      }
    }

    this.updatedAt = new Date().toISOString();
    return this;
  }

  // Change password
  async changePassword(currentPassword, newPassword) {
    const isValidCurrentPassword = await this.comparePassword(currentPassword);

    if (!isValidCurrentPassword) {
      throw new Error('Current password is incorrect');
    }

    this.password = newPassword;
    await this.hashPassword();
    this.updatedAt = new Date().toISOString();

    return this;
  }
}

module.exports = User;

const normalizeEmail = (email) => (email || '').toLowerCase().trim();

// MongoDB User Schema
const userSchema = new mongoose.Schema({
  name: {
    type: String,
    required: true,
    trim: true
  },
  email: {
    type: String,
    required: true,
    unique: true,
    lowercase: true,
    trim: true
  },
  password: {
    type: String,
    required: function() { return !this.isTemporary; },
    minlength: 6
  },
  emailVerified: {
    type: Boolean,
    default: false
  },
  isTemporary: {
    type: Boolean,
    default: false
  },
  profile: {
    bio: { type: String, default: '' },
    skills: [{ type: String }],
    experience: { type: String, default: '' },
    linkedin: { type: String, default: '' },
    github: { type: String, default: '' },
    portfolio: { type: String, default: '' },
    location: { type: String, default: '' },
    avatar: { type: String, default: '' },
    isPublic: { type: Boolean, default: false }
  },
  friends: {
    type: [{
      email: { type: String, required: true },
      addedAt: { type: Date, default: Date.now }
    }],
    default: []
  },
  friendRequests: {
    sent: {
      type: [{
        email: { type: String, required: true },
        sentAt: { type: Date, default: Date.now }
      }],
      default: []
    },
    received: {
      type: [{
        email: { type: String, required: true },
        receivedAt: { type: Date, default: Date.now }
      }],
      default: []
    }
  },
  loginAttempts: {
    type: Number,
    default: 0
  },
  lockUntil: Date,
  lastLogin: Date,
  hackathonsWon: { type: Number, default: 0 },
  hackathonsParticipated: { type: Number, default: 0 },
  currentTeam: {
    hackathonEmail: String,
    teamName: String,
    role: { type: String, enum: ['leader', 'member'], default: 'member' }
  }
}, {
  timestamps: true
});

// Virtual for checking if account is locked
userSchema.virtual('isLocked').get(function() {
  return !!(this.lockUntil && this.lockUntil > Date.now());
});

// Pre-save middleware to hash password
userSchema.pre('save', async function(next) {
  if (!this.isModified('password')) return next();

  try {
    const saltRounds = 12;
    this.password = await bcrypt.hash(this.password, saltRounds);
    next();
  } catch (error) {
    next(error);
  }
});

// Instance method to compare password
userSchema.methods.comparePassword = async function(candidatePassword) {
  return await bcrypt.compare(candidatePassword, this.password);
};

// Instance method to generate auth token
userSchema.methods.generateAuthToken = function() {
  const crypto = require('crypto');
  return crypto.randomBytes(32).toString('hex');
};

// Ensure email uniqueness at database level
userSchema.index({ email: 1 }, { unique: true });

// Instance method to convert to JSON (hide password)
userSchema.methods.toJSON = function() {
  const user = this.toObject();
  delete user.password;
  delete user.loginAttempts;
  delete user.lockUntil;
  return user;
};

// Static method to authenticate user
userSchema.statics.authenticate = async function(email, password) {
  const user = await this.findOne({ email: email.toLowerCase().trim() });

  if (!user) {
    throw new Error('Invalid email or password');
  }

  // Check if account is locked
  if (user.isLocked) {
    const remainingTime = Math.ceil((user.lockUntil - Date.now()) / 60000);
    throw new Error(`Account locked. Try again in ${remainingTime} minutes`);
  }

  // Verify password
  const isValidPassword = await user.comparePassword(password);

  if (!isValidPassword) {
    // Increment login attempts
    user.loginAttempts += 1;

    // Lock account after 5 failed attempts
    if (user.loginAttempts >= 5) {
      user.lockUntil = Date.now() + (15 * 60 * 1000); // 15 minutes
    }

    await user.save();
    throw new Error('Invalid email or password');
  }

  // Reset login attempts on successful login
  user.loginAttempts = 0;
  user.lockUntil = undefined;
  user.lastLogin = new Date();
  await user.save();

  return user;
};

// Friend system methods
userSchema.methods.sendFriendRequest = async function(targetEmail) {
  const normalizedTarget = normalizeEmail(targetEmail);
  const normalizedSelf = normalizeEmail(this.email);

  if (!normalizedTarget) {
    throw new Error('User not found');
  }

  if (normalizedSelf === normalizedTarget) {
    throw new Error('Cannot send friend request to yourself');
  }

  // Check if already friends
  if (this.friends.some(f => normalizeEmail(f.email) === normalizedTarget)) {
    throw new Error('Already friends');
  }

  // Check if request already sent
  if (this.friendRequests.sent.some(r => normalizeEmail(r.email) === normalizedTarget)) {
    throw new Error('Friend request already sent');
  }

  // Add to sender's sent requests
  this.friendRequests.sent.push({ email: normalizedTarget });

  // Add to receiver's received requests
  const targetUser = await this.constructor.findOne({ email: normalizedTarget });
  if (!targetUser) {
    throw new Error('User not found');
  }

  targetUser.friendRequests.received.push({ email: normalizedSelf });

  // Create notification
  const Notification = require('./Notification');
  await Notification.create({
    userEmail: normalizedTarget,
    type: 'friend_request',
    title: 'New Friend Request',
    message: `${this.name} sent you a friend request`,
    data: { senderEmail: normalizedSelf, senderName: this.name }
  });

  await Promise.all([this.save(), targetUser.save()]);
  return true;
};

userSchema.methods.acceptFriendRequest = async function(senderEmail) {
  const normalizedSender = normalizeEmail(senderEmail);
  const normalizedSelf = normalizeEmail(this.email);

  // Check if request exists
  const requestIndex = this.friendRequests.received.findIndex(
    r => normalizeEmail(r.email) === normalizedSender
  );
  if (requestIndex === -1) {
    throw new Error('Friend request not found');
  }

  // Add to both users' friends lists
  this.friends.push({ email: normalizedSender });

  const senderUser = await this.constructor.findOne({ email: normalizedSender });
  if (!senderUser) {
    throw new Error('User not found');
  }
  senderUser.friends.push({ email: normalizedSelf });

  // Remove from requests
  this.friendRequests.received.splice(requestIndex, 1);
  const sentIndex = senderUser.friendRequests.sent.findIndex(
    r => normalizeEmail(r.email) === normalizedSelf
  );
  if (sentIndex !== -1) {
    senderUser.friendRequests.sent.splice(sentIndex, 1);
  }

  // Create notification for sender
  const Notification = require('./Notification');
  await Notification.create({
    userEmail: normalizedSender,
    type: 'friend_accepted',
    title: 'Friend Request Accepted',
    message: `${this.name} accepted your friend request`,
    data: { accepterEmail: normalizedSelf, accepterName: this.name }
  });

  await Promise.all([this.save(), senderUser.save()]);
  return true;
};

userSchema.methods.rejectFriendRequest = async function(senderEmail) {
  const normalizedSender = normalizeEmail(senderEmail);
  const normalizedSelf = normalizeEmail(this.email);

  const requestIndex = this.friendRequests.received.findIndex(
    r => normalizeEmail(r.email) === normalizedSender
  );
  if (requestIndex === -1) {
    throw new Error('Friend request not found');
  }

  this.friendRequests.received.splice(requestIndex, 1);

  const senderUser = await this.constructor.findOne({ email: normalizedSender });
  if (!senderUser) {
    throw new Error('User not found');
  }
  const sentIndex = senderUser.friendRequests.sent.findIndex(
    r => normalizeEmail(r.email) === normalizedSelf
  );
  if (sentIndex !== -1) {
    senderUser.friendRequests.sent.splice(sentIndex, 1);
  }

  await Promise.all([this.save(), senderUser.save()]);
  return true;
};

userSchema.methods.removeFriend = async function(friendEmail) {
  const normalizedFriend = normalizeEmail(friendEmail);
  const normalizedSelf = normalizeEmail(this.email);

  const friendIndex = this.friends.findIndex(
    f => normalizeEmail(f.email) === normalizedFriend
  );
  if (friendIndex === -1) {
    throw new Error('Not friends');
  }

  this.friends.splice(friendIndex, 1);

  const friendUser = await this.constructor.findOne({ email: normalizedFriend });
  if (!friendUser) {
    throw new Error('User not found');
  }
  const userIndex = friendUser.friends.findIndex(
    f => normalizeEmail(f.email) === normalizedSelf
  );
  if (userIndex !== -1) {
    friendUser.friends.splice(userIndex, 1);
  }

  await Promise.all([this.save(), friendUser.save()]);
  return true;
};

userSchema.methods.isFriendWith = function(email) {
  const normalized = normalizeEmail(email);
  return this.friends.some(f => normalizeEmail(f.email) === normalized);
};

module.exports = mongoose.model('User', userSchema);

