    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    body: req.body,
    timestamp: new Date().toISOString()
  });

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json(
      createErrorResponse('VALIDATION_ERROR', err.message, err.details)
    );
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json(
      createErrorResponse('UNAUTHORIZED', 'Authentication required')
    );
  }

  if (err.code === 'RATE_LIMIT_EXCEEDED') {
    return res.status(429).json(
      createErrorResponse('RATE_LIMIT_EXCEEDED', err.message)
    );
  }

  // Default server error
  res.status(500).json(
    createErrorResponse('SERVER_ERROR', 'Internal server error', err.message, 500)
  );
};

// Async error wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

module.exports = {
  errorHandler,
  createErrorResponse,
  asyncHandler
};

const { logger, performanceTracker } = require('../utils/logger');

// System metrics collection
class MetricsCollector {
  constructor() {
    this.metrics = {
      requests: {
        total: 0,
        success: 0,
        errors: 0,
        byEndpoint: new Map(),
        byStatusCode: new Map()
      },
      otp: {
        generated: 0,
        verified: 0,
        failed: 0,
        expired: 0,
        resent: 0
      },
      email: {
        sent: 0,
        failed: 0,
        deliveryTime: []
      },
      performance: {
        responseTime: [],
        dbQueries: [],
        emailDelivery: []
      },
      security: {
        rateLimitHits: 0,
        accountLockouts: 0,
        suspiciousActivity: 0
      }
    };

    this.startTime = Date.now();
  }

  // Request metrics
  recordRequest(method, endpoint, statusCode, duration) {
    this.metrics.requests.total++;

    if (statusCode >= 200 && statusCode < 400) {
      this.metrics.requests.success++;
    } else {
      this.metrics.requests.errors++;
    }

    // Track by endpoint
    const endpointKey = `${method} ${endpoint}`;
    const endpointStats = this.metrics.requests.byEndpoint.get(endpointKey) || { count: 0, totalTime: 0 };
    endpointStats.count++;
    endpointStats.totalTime += duration;
    this.metrics.requests.byEndpoint.set(endpointKey, endpointStats);

    // Track by status code
    const statusStats = this.metrics.requests.byStatusCode.get(statusCode) || 0;
    this.metrics.requests.byStatusCode.set(statusCode, statusStats + 1);

    // Record response time
    this.metrics.performance.responseTime.push(duration);

    // Keep only last 1000 response times
    if (this.metrics.performance.responseTime.length > 1000) {
      this.metrics.performance.responseTime.shift();
    }
  }

  // OTP metrics
  recordOtpGenerated() {
    this.metrics.otp.generated++;
  }

  recordOtpVerified(success) {
    if (success) {
      this.metrics.otp.verified++;
    } else {
      this.metrics.otp.failed++;
    }
  }

  recordOtpExpired() {
    this.metrics.otp.expired++;
  }

  recordOtpResent() {
    this.metrics.otp.resent++;
  }

  // Email metrics
  recordEmailSent(success, deliveryTime) {
    if (success) {
      this.metrics.email.sent++;
      if (deliveryTime) {
        this.metrics.email.deliveryTime.push(deliveryTime);
        // Keep only last 100 delivery times
        if (this.metrics.email.deliveryTime.length > 100) {
          this.metrics.email.deliveryTime.shift();
        }
      }
    } else {
      this.metrics.email.failed++;
    }
  }

  // Security metrics
  recordRateLimitHit() {
    this.metrics.security.rateLimitHits++;
  }

  recordAccountLockout() {
    this.metrics.security.accountLockouts++;
  }

  recordSuspiciousActivity() {
    this.metrics.security.suspiciousActivity++;
  }

  // Get summary statistics
  getSummary() {
    const uptime = Date.now() - this.startTime;
    const responseTime = this.metrics.performance.responseTime;

    return {
      uptime: Math.floor(uptime / 1000), // seconds
      requests: {
        ...this.metrics.requests,
        successRate: this.metrics.requests.total > 0 
          ? (this.metrics.requests.success / this.metrics.requests.total * 100).toFixed(2) + '%'
          : '0%',
        avgResponseTime: responseTime.length > 0 
          ? (responseTime.reduce((a, b) => a + b, 0) / responseTime.length).toFixed(2) + 'ms'
          : '0ms'
      },
      otp: {
        ...this.metrics.otp,
        successRate: this.metrics.otp.verified + this.metrics.otp.failed > 0
          ? (this.metrics.otp.verified / (this.metrics.otp.verified + this.metrics.otp.failed) * 100).toFixed(2) + '%'
          : '0%'
      },
      email: {
        ...this.metrics.email,
        successRate: this.metrics.email.sent + this.metrics.email.failed > 0
          ? (this.metrics.email.sent / (this.metrics.email.sent + this.metrics.email.failed) * 100).toFixed(2) + '%'
          : '0%',
        avgDeliveryTime: this.metrics.email.deliveryTime.length > 0
          ? (this.metrics.email.deliveryTime.reduce((a, b) => a + b, 0) / this.metrics.email.deliveryTime.length).toFixed(2) + 'ms'
          : '0ms'
      },
      security: this.metrics.security
    };
  }

  // Reset metrics
  reset() {
    this.metrics = {
      requests: { total: 0, success: 0, errors: 0, byEndpoint: new Map(), byStatusCode: new Map() },
      otp: { generated: 0, verified: 0, failed: 0, expired: 0, resent: 0 },
      email: { sent: 0, failed: 0, deliveryTime: [] },
      performance: { responseTime: [], dbQueries: [], emailDelivery: [] },
      security: { rateLimitHits: 0, accountLockouts: 0, suspiciousActivity: 0 }
    };
    this.startTime = Date.now();
  }
}

// Global metrics collector instance
const metricsCollector = new MetricsCollector();

// Middleware for collecting request metrics
const metricsMiddleware = (req, res, next) => {
  const startTime = process.hrtime.bigint();

  // Override res.json to capture metrics
  const originalJson = res.json;
  res.json = function(data) {
    const endTime = process.hrtime.bigint();
    const duration = Number(endTime - startTime) / 1000000; // Convert to milliseconds

    metricsCollector.recordRequest(req.method, req.route?.path || req.path, res.statusCode, duration);

    return originalJson.call(this, data);
  };

  next();
};

// Health check endpoint
const healthCheck = (req, res) => {
  const health = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    metrics: metricsCollector.getSummary()
  };

  // Check critical systems
  const checks = {
    memory: process.memoryUsage().heapUsed < 500 * 1024 * 1024, // Less than 500MB
    uptime: process.uptime() > 0,
    responseTime: true // Could add more sophisticated checks
  };

  const allHealthy = Object.values(checks).every(check => check);

  res.status(allHealthy ? 200 : 503).json({
    ...health,
    status: allHealthy ? 'healthy' : 'unhealthy',
    checks
  });
};

// Detailed metrics endpoint
const metricsEndpoint = (req, res) => {
  const summary = metricsCollector.getSummary();

  res.json({
    timestamp: new Date().toISOString(),
    ...summary
  });
};

// Alert system for monitoring critical events
class AlertSystem {
  constructor() {
    this.thresholds = {
      errorRate: 10, // 10% error rate
      responseTime: 5000, // 5 seconds
      failedOtpRate: 50, // 50% failed OTP rate
      emailFailureRate: 20 // 20% email failure rate
    };

    this.alerts = [];
    this.lastCheck = Date.now();
  }

  checkAlerts() {
    const now = Date.now();
    const summary = metricsCollector.getSummary();
    const newAlerts = [];

    // Check error rate
    const errorRate = parseFloat(summary.requests.successRate.replace('%', ''));
    if (100 - errorRate > this.thresholds.errorRate) {
      newAlerts.push({
        type: 'HIGH_ERROR_RATE',
        message: `Error rate is ${100 - errorRate}%, threshold is ${this.thresholds.errorRate}%`,
        severity: 'critical',
        timestamp: now
      });
    }

    // Check response time
    const avgResponseTime = parseFloat(summary.requests.avgResponseTime.replace('ms', ''));
    if (avgResponseTime > this.thresholds.responseTime) {
      newAlerts.push({
        type: 'HIGH_RESPONSE_TIME',
        message: `Average response time is ${avgResponseTime}ms, threshold is ${this.thresholds.responseTime}ms`,
        severity: 'warning',
        timestamp: now
      });
    }

    // Check OTP failure rate
    const otpSuccessRate = parseFloat(summary.otp.successRate.replace('%', ''));
    if (100 - otpSuccessRate > this.thresholds.failedOtpRate) {
      newAlerts.push({
        type: 'HIGH_OTP_FAILURE_RATE',
        message: `OTP failure rate is ${100 - otpSuccessRate}%, threshold is ${this.thresholds.failedOtpRate}%`,
        severity: 'critical',
        timestamp: now
      });
    }

    // Check email failure rate
    const emailSuccessRate = parseFloat(summary.email.successRate.replace('%', ''));
    if (100 - emailSuccessRate > this.thresholds.emailFailureRate) {
      newAlerts.push({
        type: 'HIGH_EMAIL_FAILURE_RATE',
        message: `Email failure rate is ${100 - emailSuccessRate}%, threshold is ${this.thresholds.emailFailureRate}%`,
        severity: 'warning',
        timestamp: now
      });
    }

    // Log new alerts
    newAlerts.forEach(alert => {
      logger.warn(`ALERT: ${alert.type}`, alert);
      this.alerts.push(alert);
    });

    // Keep only last 100 alerts
    if (this.alerts.length > 100) {
      this.alerts = this.alerts.slice(-100);
    }

    this.lastCheck = now;
    return newAlerts;
  }

  getActiveAlerts() {
    const oneHourAgo = Date.now() - 60 * 60 * 1000;
    return this.alerts.filter(alert => alert.timestamp > oneHourAgo);
  }
}

const alertSystem = new AlertSystem();

// Run alert checks every 5 minutes
setInterval(() => {
  alertSystem.checkAlerts();
}, 5 * 60 * 1000);

module.exports = {
  metricsCollector,
  metricsMiddleware,
  healthCheck,
  metricsEndpoint,
  alertSystem,
  MetricsCollector,
  AlertSystem
};

const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const crypto = require('crypto');

// JWT secret - MUST be set via environment variable in production
const JWT_SECRET = process.env.JWT_SECRET || 'your-super-secret-jwt-key-change-in-production';
const JWT_EXPIRES_IN = process.env.JWT_EXPIRES_IN || '7d';

if (!process.env.JWT_SECRET) {
  console.warn('⚠️  WARNING: JWT_SECRET not set in environment variables. Using fallback key. Set JWT_SECRET in .env for production!');
}

// Password hashing
const hashPassword = async (password) => {
  const saltRounds = 12;
  return await bcrypt.hash(password, saltRounds);
};

const comparePassword = async (password, hashedPassword) => {
  return await bcrypt.compare(password, hashedPassword);
};

// JWT token management
const generateToken = (payload) => {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN });
};

const verifyToken = (token) => {
  try {
    return jwt.verify(token, JWT_SECRET);
  } catch (error) {
    throw new Error('Invalid or expired token');
  }
};

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({
      success: false,
      error: {
        code: 'UNAUTHORIZED',
        message: 'Access token required'
      }
    });
  }

  try {
    const decoded = verifyToken(token);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({
      success: false,
      error: {
        code: 'FORBIDDEN',
        message: 'Invalid or expired token'
      }
    });
  }
};

// Generate secure random string
const generateSecureRandom = (length = 32) => {
  return crypto.randomBytes(length).toString('hex');
};

// Account lockout tracking
const accountLockouts = new Map();

const checkAccountLockout = (identifier) => {
  const lockoutData = accountLockouts.get(identifier);

  if (!lockoutData) {
    return { locked: false };
  }

  const now = Date.now();

  // Check if lockout has expired
  if (lockoutData.lockedUntil < now) {
    accountLockouts.delete(identifier);
    return { locked: false };
  }

  return {
    locked: true,
    lockedUntil: lockoutData.lockedUntil,
    remainingTime: Math.ceil((lockoutData.lockedUntil - now) / 1000)
  };
};

const recordFailedAttempt = (identifier, maxAttempts = 5, lockoutDuration = 15 * 60 * 1000) => {
  const now = Date.now();
  let lockoutData = accountLockouts.get(identifier);

  if (!lockoutData) {
    lockoutData = {
      attempts: 1,
      firstAttempt: now,
      lockedUntil: 0
    };
  } else {
    lockoutData.attempts++;
  }

  // Lock account if max attempts exceeded
  if (lockoutData.attempts >= maxAttempts) {
    lockoutData.lockedUntil = now + lockoutDuration;
    console.log(`🔒 Account locked: ${identifier} for ${lockoutDuration / 1000} seconds`);
  }

  accountLockouts.set(identifier, lockoutData);

  return {
    attempts: lockoutData.attempts,
    maxAttempts,
    locked: lockoutData.lockedUntil > now,
    lockedUntil: lockoutData.lockedUntil
  };
};

const clearFailedAttempts = (identifier) => {
  accountLockouts.delete(identifier);
};

// IP-based rate limiting
const ipAttempts = new Map();

const checkIpRateLimit = (ip, maxAttempts = 20, windowMs = 15 * 60 * 1000) => {
  const now = Date.now();
  let ipData = ipAttempts.get(ip);

  if (!ipData || (now - ipData.windowStart) > windowMs) {
    ipData = {
      attempts: 1,
      windowStart: now
    };
  } else {
    ipData.attempts++;
  }

  ipAttempts.set(ip, ipData);

  return {
    attempts: ipData.attempts,
    maxAttempts,
    blocked: ipData.attempts >= maxAttempts,
    remainingTime: Math.max(0, windowMs - (now - ipData.windowStart))
  };
};

// Clean up expired entries periodically
setInterval(() => {
  const now = Date.now();
  const windowMs = 15 * 60 * 1000;

  // Clean up account lockouts
  for (const [key, data] of accountLockouts.entries()) {
    if (data.lockedUntil < now) {
      accountLockouts.delete(key);
    }
  }

  // Clean up IP attempts
  for (const [key, data] of ipAttempts.entries()) {
    if ((now - data.windowStart) > windowMs) {
      ipAttempts.delete(key);
    }
  }
}, 5 * 60 * 1000); // Clean up every 5 minutes

module.exports = {
  hashPassword,
  comparePassword,
  generateToken,
  verifyToken,
  authenticateToken,
  generateSecureRandom,
  checkAccountLockout,
  recordFailedAttempt,
  clearFailedAttempts,
  checkIpRateLimit
};

const jwt = require('jsonwebtoken');
const UserMongoDB = require('../models/UserMongoDB');

// Socket.IO authentication middleware
const socketAuth = async (socket, next) => {
  try {
    // Get token from handshake auth or query
    const token = socket.handshake.auth.token || socket.handshake.query.token;

    if (!token) {
      return next(new Error('Authentication token required'));
    }

    // Handle test tokens for development
    if (process.env.NODE_ENV === 'development' && token.startsWith('test-token')) {
      socket.userId = 'test-user';
      socket.userEmail = 'test@example.com';
      socket.userName = 'Test User';
      socket.user = {
        id: 'test-user',
        email: 'test@example.com',
        name: 'Test User'
      };
      console.log(`🧪 Test socket authenticated: ${socket.userName}`);
      return next();
    }

    // For production tokens, try JWT first (primary auth method)
    let decoded;

    try {
      // Try JWT verification (current system)
      decoded = jwt.verify(token, process.env.JWT_SECRET || 'your-super-secret-jwt-key-change-in-production');
    } catch (jwtError) {
      // If JWT fails, try base64 (backward compatibility)
      try {
        const decodedString = Buffer.from(token, 'base64').toString('utf-8');
        decoded = JSON.parse(decodedString);
      } catch (error) {
        console.error('❌ Token decode failed:', jwtError.message, error.message);
        return next(new Error('Invalid authentication token'));
      }
    }

    if (!decoded.id || !decoded.email) {
      return next(new Error('Invalid token payload'));
    }

    // Verify user exists in database
    const user = await UserMongoDB.findById(decoded.id);
    if (!user) {
      return next(new Error('User not found'));
    }

    // Attach user info to socket
    socket.userId = decoded.id;
    socket.userEmail = decoded.email;
    socket.userName = decoded.name || user.name;
    socket.user = {
      id: decoded.id,
      email: decoded.email,
      name: decoded.name || user.name
    };

    console.log(`🔌 Socket authenticated: ${socket.userName} (${socket.userEmail})`);
    next();

  } catch (error) {
    console.error('❌ Socket authentication failed:', error.message);
    next(new Error('Authentication failed'));
  }
};

// Middleware to verify user is participant of hackathon world
const verifyWorldParticipant = (hackathonWorldId) => {
  return async (socket, next) => {
    try {
      const HackathonWorld = require('../models/HackathonWorld');

      const world = await HackathonWorld.findById(hackathonWorldId);
      if (!world) {
        return next(new Error('Hackathon world not found'));
      }

      const isParticipant = world.participants.some(p => p.userId.toString() === socket.userId);
      if (!isParticipant) {
        return next(new Error('User is not a participant of this hackathon world'));
      }

      socket.hackathonWorldId = hackathonWorldId;
      next();

    } catch (error) {
      console.error('❌ World participant verification failed:', error.message);
      next(new Error('World access verification failed'));
    }
  };
};

// Middleware to verify user is member of team
const verifyTeamMember = (teamId) => {
  return async (socket, next) => {
    try {
      const Team = require('../models/Team');

      const team = await Team.findById(teamId);
      if (!team) {
        return next(new Error('Team not found'));
      }

      const isLeader = team.leader.toString() === socket.userId;
      const isMember = team.members.some(m => m.userId.toString() === socket.userId);

      if (!isLeader && !isMember) {
        return next(new Error('User is not a member of this team'));
      }

      socket.teamId = teamId;
      socket.isTeamLeader = isLeader;
      next();

    } catch (error) {
      console.error('❌ Team member verification failed:', error.message);
      next(new Error('Team access verification failed'));
    }
  };
};

module.exports = {
  socketAuth,
  verifyWorldParticipant,
  verifyTeamMember
};

const { body, validationResult } = require('express-validator');

// Validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Invalid input data',
        details: errors.array().map(err => ({
          field: err.path,
          message: err.msg,
          value: err.value
        }))
      }
    });
  }
  next();
};

// Email validation rules
const validateEmail = [
  body('email')
    .isEmail()
    .withMessage('Please provide a valid email address')
    .normalizeEmail()
    .toLowerCase(),
  validateRequest
];

// OTP validation rules
const validateOtp = [
  body('otp')
    .isLength({ min: 6, max: 6 })
    .withMessage('OTP must be exactly 6 digits')
    .isNumeric()
    .withMessage('OTP must contain only numbers'),
  validateRequest
];

// Registration validation rules
const validateRegistration = [
  body('name')
    .trim()
    .isLength({ min: 2, max: 50 })
    .withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z0-9\s._-]+$/)
    .withMessage('Name can only contain letters, numbers, spaces, dots, underscores, and hyphens'),
  body('email')
    .isEmail()
    .withMessage('Please provide a valid email address')
    .normalizeEmail()
    .toLowerCase(),
  body('password')
    .isLength({ min: 6, max: 128 })
    .withMessage('Password must be at least 6 characters long'),
  validateRequest
];

// Login validation rules
const validateLogin = [
  body('email')
    .isEmail()
    .withMessage('Please provide a valid email address')
    .normalizeEmail()
    .toLowerCase(),
  body('password')
    .notEmpty()
    .withMessage('Password is required'),
  validateRequest
];

module.exports = {
  validateEmail,
  validateOtp,
  validateRegistration,
  validateLogin,
  validateRequest
};

