messageSchema.methods.deleteMessage = function(userId) {
  // Only sender can delete
  if (this.sender.toString() !== userId.toString()) {
    throw new Error('Only message sender can delete this message');
  }

  this.isDeleted = true;
  this.deletedAt = new Date();

  return this.save();
};

