  // Remove existing reaction from this user
  this.reactions = this.reactions.filter(r => r.userId.toString() !== userId.toString());

  // Add new reaction
  this.reactions.push({
    userId,
    emoji,
    createdAt: new Date()
  });

  return this.save();
};

